// General Backtracking Template
// Ye template dikhata hai ki backtracking ka basic structure kya hota hai

void backtrack(int choices[], int n, int current[], int depth) {
    // Base case: agar solution complete ho gaya
    if (depth == n) {
        // Process the solution
        for (int i = 0; i < n; i++)
            cout << current[i] << " ";
        cout << endl;
        return;
    }

    // Har possible choice try karo
    for (int i = 0; i < n; i++) {
        // Check if this choice is promising (valid)
        if (isPromising(current, depth, choices[i])) {
            current[depth] = choices[i];  // Make choice
            backtrack(choices, n, current, depth + 1);  // Recurse
            current[depth] = -1;  // Undo choice (backtrack)
        }
        // Agar promising nahi hai toh ye branch prune ho jaati hai
    }
}

