#include <iostream>
#include <vector>
using namespace std;

bool isSafe(vector<vector<int>>& board, int row, int col, int n) {
    // Same row mein left side check karo
    for (int j = 0; j < col; j++)
        if (board[row][j]) return false;

    // Upper-left diagonal check karo
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--)
        if (board[i][j]) return false;

    // Lower-left diagonal check karo
    for (int i = row, j = col; i < n && j >= 0; i++, j--)
        if (board[i][j]) return false;

    return true;
}

void solveNQueens(vector<vector<int>>& board, int col, int n, int& count) {
    if (col == n) {
        count++;
        // Print the board
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++)
                cout << (board[i][j] ? "Q " : ". ");
            cout << endl;
        }
        cout << endl;
        return;
    }

    for (int row = 0; row < n; row++) {
        if (isSafe(board, row, col, n)) {
            board[row][col] = 1;  // Queen place karo
            solveNQueens(board, col + 1, n, count);
            board[row][col] = 0;  // Backtrack - queen hatao
        }
    }
}

